  "ui0075": "Normálne prihlásenie cez ChatGPT nemožno použiť ako prístup k API pre samostatnú webovú stránku, takže MedalForge nezobrazuje zavádzajúce tlačidlo „Prihlásiť sa pomocou ChatGPT“. Keď sú online obrázky povolené, vlastník aplikácie poskytuje službu a môže ju zahrnúť do plateného plánu MedalForge.",
  "ui0076": "Malá zbierka leštených východiskových bodov s dôrazom na tlač. Každý riadok, slovo, farba, strana a príloha pásky zostáva upraviteľné.",
