  "ui0147": "Vyberte zdrojový obrázok. Pred umiestnením na medailu sa otvorí v editore obrázkov na tlač, kde ho môžete orezať, odstrániť pozadie, zjednodušiť detaily, oddeliť farby a vybrať vrstvy vlákna.",
