  "ui0152": "Vyberte Pridať, potom Text, zadajte text, nastavte jeho počiatočnú veľkosť a umiestnite ho.",
  "ui0153": "Vyberte ľubovoľnú položku a upravte jej znenie, veľkosť, farbu, výšku alebo stranu. Položky vyššie v tomto zozname sa zobrazia vpredu, keď sa návrhy prekrývajú. Zadné časti sa vždy tlačia ako ploché farby prvej vrstvy.",
  "ui0154": "Vyberte farby, skontrolujte vrstvy, ktoré sa dajú vytlačiť, a potom otvorte položku Kontrola a exportujte.",
  "ui0155": "Zvoľte Kresliť pre vlastné čiary, nastavte tlačiteľnú šírku, dokončite skicu a skontrolujte ju v 3D.",
  "ui0156": "Vyberte položku Nová medaila a vyberte si tvar tela, veľkosť a pripevnenie stuhy.",
  "ui0157": "Vyberte farbu Vyvýšená, Zapustená alebo Plochá a ukážte si presnú výšku v 3D.",
  "ui0158": "Vyberte farby, ktoré chcete vytlačiť. Podrobnosti o tlačiarni sú už nastavené na bezpečné predvolené hodnoty a možno ich otvoriť iba vtedy, keď ich potrebujete.",
