  "ui0635": "Toto vlákno je už priradené k inému slotu",
  "ui0636": "Toto vlákno už nie je v miestnom katalógu",
  "ui0637": "Ten obrys sa kríži alebo dotýka sám seba. Upravte cestu predtým, ako ju použijete ako telo medaily.",
  "ui0638": "Táto uložená medaila sa na tomto zariadení nenašla",
  "ui0639": "Telo môže mať hrúbku 1,2–{baseThicknessMax2} mm. Vyvýšené umelecké dielo a okraj sú nad ním, takže hotové maximum môže byť o niečo hrubšie.",
  "ui0640": "Okraj je skutočná viacfarebná geometria v 3D náhľade, cenovej ponuke, 3MF, STL a technickom liste.",
  "ui0641": "Celý obrázok sa bude pohybovať, meniť mierku, prefarbovať a meniť výšku ako jeden kus.",
  "ui0642": "Kópiu tu nebolo možné uložiť; namiesto toho bol stiahnutý záložný súbor",
  "ui0643": "Aktuálna medaila sa sem nedala uložiť, preto bola stiahnutá záloha. Je stále otvorený a nezmenený.",
  "ui0644": "Sprievodca nasadením uchováva obe cesty inovácie oddelené, takže statický editor nikdy nepredstiera, že je k dispozícii chýbajúca služba.",
  "ui0645": "Presná sieť mení vlákno pred vrstvou{value} {join}{value2}. Pridajte pauzy na tieto fyzické vrstvy a potvrďte ich vo svojom filtri.",
  "ui0646": "Presná sieť potrebuje približne {toFixed} g vrátane čistenia a 8 % produkčnej rezervy; miestne zásoby sú {toFixed2} g.",
  "ui0647": "Príklad si zachováva svoje testované telo {diameter} mm {escapeHtml}",
  "ui0648": "Exportované telo nebude mať otvorenie pásky.",
  "ui0649": "Finálne 3D telo nie je uzavreté",
  "ui0650": "Skupina sa pohybuje ako jedna nezvratná zmena. Každá položka si zachováva svoj upraviteľný text, farbu a štýl povrchu.",
  "ui0651": "Riadené nastavenie vyžaduje telo, pripevnenie pásky a podrobnosti o udalosti.",
  "ui0652": "Miestny katalóg filamentov je plný. Pred vytvorením ďalšieho záznamu odstráňte nepoužívaný záznam.",
  "ui0653": "Telo medaily je rozdelené na rozpojené nábojnice {value}. Pretvarujte rez, kým korpus nezostane z jedného kusu.",
  "ui0654": "Pôvodný súbor nikdy neopustí tento počítač. Pred umiestnením čohokoľvek na medailu si ju prezriete a vyčistíte.",
  "ui0655": "Náhľad samostatne zobrazuje presné telo a hotovú veľkosť s prílohou.",
  "ui0656": "Ukážky nižšie sú nakreslené z každej upraviteľnej medaily – nie makety umeleckého diela.",
  "ui0657": "Stuha a štúdiové pozadie boli orezané. Farby tváre a okrajov sa stanú nastaveniami medailí; umelecké diela a nápisy sa stávajú samostatnými objektmi.",
  "ui0658": "Zvolený filament tu nahrádza materiál medaily za {toFixed} mm ({layerCountLabel}). Vonkajší zadný povrch zostáva dokonale rovný.",
  "ui0659": "Symbol zostáva vektorovo hladký a upraviteľný pomocou hranatých rohových rukovätí. Detailné vodiace lišty fungujú najlepšie pri 24 mm alebo väčších.",
  "ui0660": "Transformovaná skupina by opustila tlačiteľnú tvár",
  "ui0661": "Spodná strana zostáva na stavebnej doske.",
  "ui0662": "Video sa nepodarilo načítať. Stále si môžete prečítať kroky alebo reštartovať interaktívneho sprievodcu.",
  "ui0663": "Toto sú dočasné pravidlá. Pred komerčnou výrobou vytlačte kalibračné kupóny pre každú tlačiareň, rezač, materiálový rad, rýchlosť a dizajn páskovej slučky a potom nahraďte predvolené hodnoty nameranými profilmi.",
  "ui0664": "Tieto kontroly využívajú vašu medailu, umelecké dielo, trysku, výšku vrstvy a vybrané vlákna. Tu opravte červené položky, prezrite si oranžové rady a potom vždy pred tlačou otvorte stiahnutý súbor vo svojom filtri.",
  "ui0665": "Toto umelecké dielo nemá žiadny upraviteľný zdrojový obrázok",
  "ui0666": "Tento prehliadač nemohol uložiť kópiu; namiesto toho bol stiahnutý záložný súbor",
  "ui0667": "Tento výrez je príliš úzky na to, aby sa jeho pomer udržal v podporovanom rozsahu veľkostí. Najprv odomknite pomer.",
  "ui0668": "Táto plodina je príliš úzka na zachovanie jej pomeru. Pred použitím pomer odblokujte.",
  "ui0669": "Tento dizajn má priestor pre ďalšie objekty {max}, ale toto umelecké dielo obsahuje {assemblyCount}. Najskôr odstráňte niekoľko častí.",
  "ui0670": "Tento dizajn dosiahol bezpečný rozpočet prehliadača objektov {elements}",
  "ui0671": "Tento dizajn dosiahol bezpečný rozpočet prehliadača skupiny {groups}",
  "ui0672": "Táto detekovaná časť obrazu je nezávislá. Zmena jeho farby neovplyvní ostatné časti v jeho skupine.",
  "ui0673": "Táto skupina nemá na tejto tvári žiadne objekty",
  "ui0674": "Táto skupina nemá žiadne objekty na duplikovanie",
  "ui0675": "Toto je skutočný obrys zhora vrátane každého otvoru. Po otvorení zostane plne upraviteľný v nástroji Medal.",
  "ui0676": "Toto je presne ten istý obrys tela a pásky, ktorý sa otvára v otočnom 3D pracovnom priestore. Pridajte objekt, prejdite po prednej alebo zadnej strane a kliknite len vtedy, keď je jeho skutočný náhľad na správnom mieste.",
  "ui0677": "Toto je hosťovaná statická edícia s nulovými nákladmi. Webová stránka nemá povolené ticho sťahovať, inštalovať alebo spúšťať program AI na počítači návštevníka a toto nasadenie nemá žiadne platené rozhranie API.",
  "ui0678": "Táto vrstva potrebuje viac ako jednu farbu naraz",
  "ui0679": "Táto lokálna zostava nezahŕňa online generovanie. Vyberte si",
  "ui0680": "Táto medaila môže použiť až {paletteSlots} farieb",
  "ui0681": "Tento vyleštený príklad už obsahuje upraviteľné znenie",
  "ui0682": "To bráni tomu, aby jeho kresba prekročila okraj tlače. Po otvorení môžete stále zmeniť telo pod medailou a živé kontroly vás povedú.",
  "ui0683": "Tento príklad kontroly kvality je dočasný",
  "ui0684": "Prierez vytvára voľný kus",
  "ui0685": "Prepnúť {escapeHtml2}",
  "ui0686": "Horná časť nad tvárou",
  "ui0687": "Vrchná vložka",
  "ui0688": "Vrchný povrch",
  "ui0689": "Priesvitný",
  "ui0690": "Napíšte tento riadok presne",
  "ui0691": "Nedostupné vlákna zostávajú viditeľné pre referenciu. Farba, ktorú už táto medaila používa, vyberie jej existujúci slot namiesto vytvorenia duplikátu.",
  "ui0692": "Rozumel",
  "ui0693": "Zrušte poslednú zmenu",
  "ui0694": "vrátiť späť · šípky posúvajú",
  "ui0695": "Neznámy",
  "ui0696": "Pred zmenou skupiny odomknite v položkách dizajnu.",
  "ui0697": "Aktualizuje sa obrázok {length}{value} pre {reason}…",
  "ui0698": "Aktualizuje sa lokálne…",
  "ui0699": "Nahrávanie, čistenie obrázkov, separácia farieb, prevod textu na medailu, 3D úpravy a exporty",
  "ui0700": "Použite medailu s najvyšším skóre · {toFixed}/10",
  "ui0701": "Použite môj obrázok",
  "ui0702": "Použiť môj vlastný obrys medaily",
  "ui0703": "Pred zmenou vlastností objektu použite na modeli OK alebo Zrušiť.",
  "ui0704": "Nastavenia použite len vtedy, keď sa zmení tryska, výška vrstvy alebo dostupné vlákna.",
  "ui0705": "Ak chcete pridať vlákno, materiál a špeciálny efekt, použite znamienko plus vedľa výberu farby.",
  "ui0706": "Použiť celý obrázok",
  "ui0707": "Užitočné pre biele umelecké diela na tmavej fotografii.",
  "ui0708": "Použitie rovnakého miestneho výškového poľa ako 3D a export.",
  "ui0709": "Zmena farby UV",
  "ui0710": "Overené telesá B-Rep prestavané z produkčnej geometrie. Vektorové objekty zostávajú hladšie ako rastrové kresby.",
  "ui0711": "Pohľad: {value}",
  "ui0712": "Vizuálny štýl",
  "ui0713": "Pred uložením kópie počkajte na dokončenie aktualizácie obrázka",
  "ui0714": "Pred exportom počkajte na dokončenie aktualizácie obrázka, ktorý možno vytlačiť",
  "ui0715": "Chcete ilustrované umelecké diela na mieru?",
  "ui0716": "Pridáme to ako ostrý, upraviteľný text. Každý riadok v 3D môžete presunúť, zmeniť jeho veľkosť, prefarbiť alebo odstrániť.",
  "ui0717": "Za čo je medaila?",
