  "ui0562": "Otočný 3D model s výběrem objektů. Tažením v prázdném místě model otáčejte, kliknutím vyberte grafiku, Shift + tažení posouvá pohled a kolečko přibližuje. Klávesnice: šipky otáčejí, Shift + šipky posouvají, plus a minus přibližují, 1 zobrazí přední stranu, 2 zadní a 0 vrátí 3D pohled.",
