  "ui0612": "Jiskřivé částice. Doporučuje se tvrzená tryska.",
  "ui0613": "Skvrnitý minerální vzhled. Doporučuje se tvrzená tryska.",
  "ui0614": "Naskládejte geometrii níže",
  "ui0615": "Začněte od čistého návrhu nebo si přizpůsobte jednu z vyladěných tisknutelných medailí zobrazených v galerii.",
  "ui0616": "Začněte od čisté medaile",
