  "ui0236": "Ziehen Sie den leeren Bereich, um ihn zu drehen. Klicken Sie auf das Bildmaterial, um dessen Höhenmarkierung anzuzeigen. Durch die Bewegung gefüllter Ebenenquerschnitte. Ziehen Sie die Umschalttaste/nach rechts, um zu schwenken. Mit dem Rad/Push-Zoom zoomen Sie",
