  "ui0269": "Acht gezielte Anleitungen zeigen den echten Editor, echte Schaltflächen und einen vollständigen Workflow für druckbare Medaillen. Jedes Video ist weniger als 30 Sekunden lang und verfügt über englische Untertitel.",
