  "ui0390": "MedalForge speichert die Medaille, die Sie bearbeiten, automatisch. Verwenden Sie Kopien, wenn Sie eine neue Richtung erkunden möchten, ohne das Original zu verändern.",
  "ui0391": "MedalForge prüft physikalische Millimeterschätzungen, nicht Bildschirmpixel. Das aktuelle Startprofil verwendet eine nominale Extrusionsbreite von 1,125× der Düse und behandelt zwei Linien als robustes, kundenorientiertes Ziel.",
