  "ui0637": "Dieser Umriss kreuzt oder berührt sich selbst. Bearbeiten Sie den Pfad, bevor Sie ihn als Medaillenkörper verwenden.",
  "ui0638": "Die gespeicherte Medaille konnte auf diesem Gerät nicht gefunden werden",
  "ui0639": "Der Körper kann 1,2–{baseThicknessMax2} mm dick sein. Das erhabene Motiv und die Kante liegen darüber, sodass das fertige Maximum etwas dicker ausfallen kann.",
  "ui0640": "Der Rand ist eine echte mehrfarbige Geometrie in der 3D-Vorschau, dem Angebot, 3MF, STL und dem technischen Datenblatt.",
  "ui0641": "Das gesamte Bild wird als Ganzes verschoben, skaliert, neu eingefärbt und in der Höhe geändert.",
  "ui0642": "Die Kopie konnte hier nicht gespeichert werden; Stattdessen wurde eine Sicherungsdatei heruntergeladen",
  "ui0643": "Die aktuelle Medaille konnte hier nicht gespeichert werden, daher wurde ein Backup heruntergeladen. Es ist weiterhin offen und unverändert.",
  "ui0644": "Der Bereitstellungsleitfaden hält beide Upgrade-Pfade getrennt, sodass der statische Editor niemals vorgibt, dass ein fehlender Dienst verfügbar ist.",
  "ui0645": "Das genaue Netz ändert das Filament vor der Schicht{value} {join}{value2}. Fügen Sie Pausen auf diesen physischen Ebenen hinzu und bestätigen Sie sie in Ihrem Slicer.",
  "ui0646": "Das genaue Netz benötigt ca. {toFixed} g inklusive Spülung und einer Produktionsreserve von 8 %; Der lokale Lagerbestand ist {toFixed2} g.",
  "ui0647": "Das Exemplar behält sein getestetes {diameter} mm {escapeHtml}-Gehäuse",
  "ui0648": "Der exportierte Körper weist keine Bandöffnung auf.",
  "ui0649": "Der endgültige 3D-Körper ist nicht geschlossen",
  "ui0650": "Die Gruppe wird als eine unwiderrufliche Änderung verschoben. Jedes Element behält seinen bearbeitbaren Text, seine Farbe und seinen Oberflächenstil.",
  "ui0651": "Bei der geführten Einrichtung werden der Text, die Bandbefestigung und die Ereignisdetails abgefragt.",
  "ui0652": "Der lokale Filamentkatalog ist voll. Entfernen Sie einen nicht verwendeten Datensatz, bevor Sie einen neuen erstellen.",
  "ui0653": "Der Medaillenkörper ist in getrennte {value}-Schalen unterteilt. Formen Sie den Schnitt um, bis der Körper einteilig bleibt.",
  "ui0654": "Die Originaldatei verlässt niemals diesen Computer. Sie sehen sich die Medaille an und reinigen sie, bevor Sie etwas auf die Medaille legen.",
  "ui0655": "Die Vorschau zeigt separat den genauen Körper und die fertige Größe mit der Anlage.",
  "ui0656": "Die folgenden Vorschauen stammen von jeder bearbeitbaren Medaille – nicht von Modellgrafiken.",
  "ui0657": "Das Band und der Studiohintergrund wurden weggeschnitten. Die Gesichts- und Randfarben werden zu Medaillen-Einstellungen; Grafik und Schrift werden zu separaten Objekten.",
  "ui0658": "Das ausgewählte Filament ersetzt hier das Medaillenmaterial für {toFixed} mm ({layerCountLabel}). Die äußere Rückseite bleibt vollkommen flach.",
  "ui0659": "Mit den quadratischen Eckgriffen bleibt das Symbol vektorglatt und bearbeitbar. Detaillierte Läufer funktionieren am besten bei 24 mm oder mehr.",
  "ui0660": "Die transformierte Gruppe würde das druckbare Gesicht verlassen",
  "ui0661": "Die Unterseite verbleibt auf der Bauplatte.",
  "ui0662": "Das Video konnte nicht geladen werden. Sie können weiterhin die Schritte lesen oder den interaktiven Leitfaden neu starten.",
  "ui0663": "Es handelt sich um vorläufige Regeln. Drucken Sie vor der kommerziellen Produktion Kalibrierungscoupons für jeden Drucker, Slicer, jede Materialfamilie, jede Geschwindigkeit und jedes Farbbandschleifendesign aus und ersetzen Sie dann die Standardwerte durch gemessene Profile.",
  "ui0664": "Bei diesen Prüfungen werden Ihre Medaille, Ihr Motiv, Ihre Düse, Ihre Schichthöhe und Ihre ausgewählten Filamente verwendet. Korrigieren Sie hier rote Elemente, lesen Sie die orangefarbenen Hinweise und öffnen Sie dann immer die heruntergeladene Datei in Ihrem Slicer, bevor Sie sie drucken.",
  "ui0665": "Dieses Kunstwerk hat kein bearbeitbares Quellbild",
  "ui0666": "Dieser Browser konnte die Kopie nicht speichern; Stattdessen wurde eine Sicherungsdatei heruntergeladen",
  "ui0667": "Dieser Zuschnitt ist zu schmal, um sein Verhältnis innerhalb des unterstützten Größenbereichs zu halten. Schalten Sie zuerst das Verhältnis frei.",
  "ui0668": "Diese Ernte ist zu eng, um ihr Verhältnis beizubehalten. Entsperren Sie das Verhältnis, bevor Sie es verwenden.",
  "ui0669": "Dieses Design bietet Platz für {max} weitere Objekte, aber dieses Kunstwerk enthält {assemblyCount}. Entfernen Sie zunächst einige Teile.",
  "ui0670": "Dieses Design erreichte das sichere {elements}-Objektbrowser-Budget",
  "ui0671": "Dieses Design erreichte das sichere Browserbudget der {groups}-Gruppe",
  "ui0672": "Dieser erkannte Bildteil ist unabhängig. Die Änderung seiner Farbe hat keine Auswirkungen auf die anderen Teile in seiner Gruppe.",
  "ui0673": "Diese Gruppe hat keine Objekte auf dieser Fläche",
  "ui0674": "Diese Gruppe verfügt über keine zu duplizierenden Objekte",
  "ui0675": "Dies ist die tatsächliche Draufsicht, einschließlich aller Öffnungen. Nach dem Öffnen bleibt es im Medaillen-Tool vollständig bearbeitbar.",
  "ui0676": "Dies ist genau derselbe Körper- und Bandumriss, der im drehbaren 3D-Arbeitsbereich geöffnet wird. Fügen Sie ein Objekt hinzu, bewegen Sie es über die Vorder- oder Rückseite und klicken Sie nur, wenn sich die tatsächliche Vorschau an der richtigen Stelle befindet.",
  "ui0677": "Dies ist die kostenfreie Hosted-Static-Edition. Einer Website ist es nicht gestattet, unbemerkt ein KI-Programm auf den Computer eines Besuchers herunterzuladen, zu installieren oder zu starten, und diese Bereitstellung verfügt über keine kostenpflichtige Bild-API.",
  "ui0678": "Diese Ebene benötigt mehr als eine Farbe gleichzeitig",
