  "ui0681": "Dieses ausgefeilte Beispiel enthält bereits editierbare Formulierungen",
  "ui0682": "Dadurch wird verhindert, dass das Bildmaterial die bedruckbare Kante überschreitet. Nach dem Öffnen können Sie den Körper immer noch unter Medaille ändern und die Live-Checks werden Sie dabei unterstützen.",
  "ui0683": "Dieses Beispiel einer Qualitätsprüfung ist vorübergehend",
