  "ui0391": "MedalForge sprawdza fizyczne szacunki w milimetrach, a nie piksele ekranu. Obecny profil początkowy wykorzystuje nominalną szerokość wytłaczania 1,125 × dyszy i traktuje dwie linie jako solidny cel skierowany do klienta.",
