  "ui0399": "Przesuń wybrany obiekt. Użyj klawiszy strzałek, aby precyzyjnie poruszać się.",
  "ui0400": "Przesuń podgląd prawdziwego tekstu na dowolną stronę i kliknij, aby go umieścić. Tekst z tyłu czyta się prawidłowo i jest automatycznie osadzany na płasko w pierwszej warstwie druku.",
  "ui0401": "Poruszaj się po wydruku po jednej warstwie fizycznej na raz. Wgłębione obszary stają się pustą przestrzenią; płaskie kolory pokazują wybrany włókno.",
