  "ui0643": "Nie udało się tutaj zapisać aktualnego medalu, więc pobrano kopię zapasową. Jest nadal otwarta i niezmieniona.",
  "ui0644": "Przewodnik wdrażania oddziela obie ścieżki aktualizacji, więc edytor statyczny nigdy nie udaje, że dostępna jest brakująca usługa.",
  "ui0645": "Dokładna siatka zmienia włókno przed warstwą{value} {join}{value2}. Dodaj pauzy w tych warstwach fizycznych i potwierdź je we fragmentatorze.",
  "ui0646": "Dokładna siatka wymaga około {toFixed} g, łącznie z oczyszczaniem i 8% rezerwą produkcyjną; magazyn lokalny to {toFixed2} g.",
  "ui0647": "Przykład zachowuje testowaną nadwozie {diameter} mm {escapeHtml}",
  "ui0648": "Wyeksportowana bryła nie będzie miała otworu na wstążkę.",
  "ui0649": "Ostateczna bryła 3D nie jest zamknięta",
  "ui0650": "Grupa porusza się jako jedna nieodwracalna zmiana. Każdy element zachowuje edytowalny tekst, kolor i styl powierzchni.",
  "ui0651": "Konfiguracja z przewodnikiem wymaga podania treści, załącznika wstążki i szczegółów wydarzenia.",
  "ui0652": "Lokalny katalog żarników jest pełny. Usuń nieużywany rekord przed utworzeniem kolejnego.",
  "ui0653": "Korpus medalu jest podzielony na odłączane korpusy {value}. Zmień kształt cięcia, aż korpus pozostanie jednym kawałkiem.",
  "ui0654": "Oryginalny plik nigdy nie opuszcza tego komputera. Przed umieszczeniem czegokolwiek na medalu obejrzysz go i wyczyścisz.",
  "ui0655": "Podgląd osobno pokazuje dokładny korpus i gotowy rozmiar z załącznikiem.",
  "ui0656": "Poniższe podglądy pochodzą z każdego edytowalnego medalu, a nie z makiety.",
  "ui0657": "Wstążka i tło studia zostały przycięte. Kolory tarczy i obręczy staną się oprawą medalu; grafika i napis stają się odrębnymi obiektami.",
  "ui0658": "Wybrany żarnik zastępuje tutaj materiał medalowy dla {toFixed} mm ({layerCountLabel}). Zewnętrzna tylna powierzchnia pozostaje idealnie płaska.",
  "ui0659": "Symbol pozostaje gładki wektorowo i można go edytować za pomocą kwadratowych uchwytów narożnych. Szczegółowe prowadnice najlepiej sprawdzają się przy średnicy 24 mm lub większej.",
  "ui0660": "Przekształcona grupa opuści powierzchnię do druku",
  "ui0661": "Spód pozostaje na płycie roboczej.",
  "ui0662": "Nie udało się załadować filmu. Nadal możesz przeczytać kroki lub ponownie uruchomić interaktywny przewodnik.",
  "ui0663": "Są to zasady tymczasowe. Przed produkcją komercyjną wydrukuj kupony kalibracyjne dla każdej drukarki, krajalnicy, rodziny materiałów, prędkości i projektu pętli wstążki, a następnie zastąp ustawienia domyślne zmierzonymi profilami.",
  "ui0664": "Te kontrole wykorzystują Twój medal, grafikę, dyszę, wysokość warstwy i wybrane włókna. Napraw tutaj czerwone elementy, przejrzyj pomarańczowe porady, a następnie zawsze otwieraj pobrany plik we fragmentatorze przed drukowaniem.",
  "ui0665": "Ta grafika nie ma edytowalnego obrazu źródłowego",
  "ui0666": "Ta przeglądarka nie mogła zapisać kopii; zamiast tego pobrano plik kopii zapasowej",
  "ui0667": "Ta uprawa jest zbyt wąska, aby utrzymać jej proporcje w obsługiwanym zakresie rozmiarów. Najpierw odblokuj współczynnik.",
  "ui0668": "Ta uprawa jest zbyt wąska, aby zachować swoje proporcje. Odblokuj współczynnik przed jego użyciem.",
  "ui0669": "W tym projekcie jest miejsce na więcej obiektów {max}, ale ta grafika zawiera {assemblyCount}. Najpierw usuń kilka części.",
  "ui0670": "Projekt ten osiągnął bezpieczny budżet przeglądarki obiektowej {elements}",
  "ui0671": "Projekt ten osiągnął bezpieczny budżet przeglądarki grupy {groups}",
  "ui0672": "Ta wykryta część obrazu jest niezależna. Zmiana jego koloru nie ma wpływu na pozostałe części w tej grupie.",
  "ui0673": "Ta grupa nie ma żadnych obiektów na tej twarzy",
  "ui0674": "W tej grupie nie ma obiektów do zduplikowania",
  "ui0675": "To jest rzeczywisty zarys widoku z góry, uwzględniający każdy otwór. Po otwarciu pozostaje w pełni edytowalny w narzędziu Medal.",
  "ui0676": "Jest to dokładnie ten sam kontur bryły i wstążki, który otwiera się w obrotowej przestrzeni roboczej 3D. Dodaj obiekt, przesuń się nad przednią lub tylną ścianą i kliknij dopiero wtedy, gdy jego rzeczywisty podgląd znajdzie się w odpowiednim miejscu.",
  "ui0677": "Jest to bezpłatna, hostowana wersja statyczna. Witryna internetowa nie może dyskretnie pobierać, instalować ani uruchamiać programu AI na komputerze odwiedzającego, a to wdrożenie nie ma interfejsu API płatnego obrazu.",
  "ui0678": "Ta warstwa wymaga więcej niż jednego koloru na raz",
  "ui0679": "Ta kompilacja lokalna nie obejmuje generowania online. Wybierz",
  "ui0680": "W tym medalu można zastosować maksymalnie kolory {paletteSlots}",
  "ui0681": "Ten dopracowany przykład zawiera już edytowalne sformułowania",
  "ui0682": "Dzięki temu grafika nie będzie przekraczać krawędzi przeznaczonej do druku. Po otwarciu nadal możesz zmienić ciało w obszarze Medal, a kontrole na żywo poprowadzą Cię.",
  "ui0683": "Ten przykład kontroli jakości ma charakter tymczasowy",
  "ui0684": "Cięcie przelotowe tworzy luźny element",
  "ui0685": "Przełącz {escapeHtml2}",
  "ui0686": "Góra nad twarzą",
  "ui0687": "Górna wstawka",
  "ui0688": "Górna powierzchnia",
  "ui0689": "Półprzezroczysty",
  "ui0690": "Wpisz dokładnie tę linię",
  "ui0691": "Niedostępne włókna pozostają widoczne w celach informacyjnych. Kolor już używany przez ten medal wybiera istniejące miejsce, zamiast tworzyć duplikat.",
  "ui0692": "Zrozumiałem",
  "ui0693": "Cofnij ostatnią zmianę",
  "ui0694": "cofnij · strzałki przesuwają",
