  "ui0697": "Aktualizowanie obrazu {length}{value} dla {reason}…",
  "ui0698": "Aktualizuję lokalnie…",
  "ui0699": "Przesyłanie, oczyszczanie obrazu, separacja kolorów, zamiana tekstu na medal, edycja 3D i eksport",
  "ui0700": "Użyj medalu z najwyższym wynikiem · {toFixed}/10",
