  "ui0702": "Użyj mojego własnego zarysu medalu",
  "ui0703": "Użyj przycisku OK lub Anuluj na modelu przed zmianą właściwości obiektu.",
  "ui0704": "Użyj Ustawień tylko wtedy, gdy zmieni się dysza, wysokość warstwy lub dostępne włókna.",
  "ui0705": "Użyj plusa obok wyboru koloru, aby dodać włókno, materiał i efekt specjalny.",
  "ui0706": "Użyj całego obrazu",
  "ui0707": "Przydatne w przypadku białych kompozycji na ciemnym zdjęciu.",
  "ui0708": "Używanie tego samego lokalnego pola wysokości co w przypadku 3D i eksportu.",
  "ui0709": "Zmiana koloru UV",
  "ui0710": "Zatwierdzone bryły B-Rep odbudowane z geometrii produkcyjnej. Obiekty wektorowe pozostają gładsze niż grafiki rastrowe.",
  "ui0711": "Widok: {value}",
  "ui0712": "Styl wizualny",
  "ui0713": "Przed zapisaniem kopii poczekaj na zakończenie aktualizacji obrazu",
  "ui0714": "Przed eksportem poczekaj na zakończenie aktualizacji obrazu nadającego się do wydruku",
