function deepFreeze(value) {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
  for (const child of Object.values(value)) deepFreeze(child);
  return Object.freeze(value);
}

export const TRANSLATIONS = Object.freeze({
  en: deepFreeze(EN),
  sk: deepFreeze(SK),
  cs: deepFreeze(CS),
  de: deepFreeze(DE),
  pl: deepFreeze(PL),
});

const LOCALE_METADATA = new Map(SUPPORTED_LOCALES.map(locale => [locale.code, locale]));

/** Resolve `de-DE`, `cs_CZ`, and similar browser locale strings safely. */
export function normalizeLocale(locale) {
  const candidate = String(locale || '').trim().toLowerCase().replace('_', '-').split('-')[0];
  const normalized = candidate === 'cz' ? 'cs' : candidate;
  return Object.hasOwn(TRANSLATIONS, normalized) ? normalized : DEFAULT_LOCALE;
}

export function localeMetadata(locale) {
  return LOCALE_METADATA.get(normalizeLocale(locale));
}

function messageAt(catalog, path) {
  return String(path || '').split('.').reduce((value, key) => (
    value && typeof value === 'object' ? value[key] : undefined
  ), catalog);
}

/**
 * Return one translated message and replace `{name}` placeholders.
 * Missing variables remain visible during development instead of disappearing.
 */
export function translateMessage(locale, key, variables = {}) {
  const normalized = normalizeLocale(locale);
  const localized = messageAt(TRANSLATIONS[normalized], key);
  const fallback = messageAt(TRANSLATIONS[DEFAULT_LOCALE], key);
  const template = typeof localized === 'string' ? localized : typeof fallback === 'string' ? fallback : String(key || '');
  return template.replace(/\{([A-Za-z_][\w.-]*)\}/gu, (token, name) => (
    Object.hasOwn(variables, name) ? String(variables[name]) : token
  ));
}

export function hasMessage(locale, key) {
  return typeof messageAt(TRANSLATIONS[normalizeLocale(locale)], key) === 'string';
}

export function formatLocaleNumber(locale, value, options = {}) {
  return new Intl.NumberFormat(localeMetadata(locale).numberLocale, options).format(Number(value));
}

export function formatLocaleCurrency(locale, value, currency = 'CZK', options = {}) {
  return new Intl.NumberFormat(localeMetadata(locale).numberLocale, {
    style: 'currency', currency, maximumFractionDigits: 0, ...options,
  }).format(Number(value));
}

export function formatLocaleDate(locale, value, options = {}) {
  const date = value instanceof Date ? value : new Date(value);
  return new Intl.DateTimeFormat(localeMetadata(locale).numberLocale, options).format(date);
}
